public class Main {
  static String[] lessThan20 = {"","One","Two","Three","Four","Five","Six","Seven","Eight","Nine","Ten","Eleven","Twelve","Thirteen","Fourteen","Fifteen","Sixteen","Seventeen","Eighteen","Nineteen"};
  static String[] tens = {"","Ten","Twenty","Thirty","Forty","Fifty","Sixty","Seventy","Eighty","Ninety"};
  static String[] thousands = {"","Thousand","Million","Billion"};
  static String convert(int n) {
    if (n == 0) return "";
    if (n < 20) return lessThan20[n];
    if (n < 100) return tens[n/10] + (n%10>0 ? " " + lessThan20[n%10] : "");
    return lessThan20[n/100] + " Hundred" + (n%100>0 ? " " + convert(n%100) : "");
  }
  static String numberToWords(int num) {
    if (num == 0) return "Zero";
    String result = "";
    int i = 0;
    while (num > 0) {
      int chunk = num % 1000;
      if (chunk > 0) {
        String chunkWords = convert(chunk);
        String mag = thousands[i];
        result = chunkWords + (mag.isEmpty() ? "" : " " + mag) + (result.isEmpty() ? "" : " " + result);
      }
      num /= 1000;
      i++;
    }
    return result;
  }
  public static void main(String[] args) {
    java.util.Scanner sc = new java.util.Scanner(System.in);
    System.out.println(numberToWords(sc.nextInt()));
  }
}
